## 1. Handwrite `src/domain/tasks/schemas.ts`

```ts
import { z } from "zod";

export const taskStatusSchema = z.enum(["todo", "doing", "done"]);

export const taskSchema = z.object({
  id: z.string().min(1),
  ownerId: z.string().min(1),
  title: z.string().trim().min(1).max(200),
  status: taskStatusSchema,
  parentTaskId: z.string().min(1).nullable(),
  position: z.number().int().nonnegative(),
  version: z.number().int().positive(),
  createdAt: z.iso.datetime(),
  updatedAt: z.iso.datetime(),
});

export type Task = z.infer<typeof taskSchema>;
export type TaskStatus = z.infer<typeof taskStatusSchema>;

/** POST /api/tasks body — client cannot set id/owner/version/timestamps */
export const createTaskSchema = z.object({
  title: z.string().trim().min(1).max(200),
  parentTaskId: z.string().min(1).nullable().optional(),
  position: z.number().int().nonnegative().optional(),
});

export type CreateTaskInput = z.infer<typeof createTaskSchema>;

/** PATCH /api/tasks/:id — at least one field; version required for concurrency */
export const updateTaskSchema = z
  .object({
    title: z.string().trim().min(1).max(200).optional(),
    status: taskStatusSchema.optional(),
    position: z.number().int().nonnegative().optional(),
    version: z.number().int().positive(),
  })
  .refine(
    (body) =>
      body.title !== undefined ||
      body.status !== undefined ||
      body.position !== undefined,
    { message: "At least one of title, status, or position is required" },
  );

export type UpdateTaskInput = z.infer<typeof updateTaskSchema>;

export const taskListQuerySchema = z.object({
  parentTaskId: z.string().min(1).nullable().optional(),
  status: taskStatusSchema.optional(),
  limit: z.coerce.number().int().min(1).max(100).default(20),
  offset: z.coerce.number().int().nonnegative().default(0),
});

export type TaskListQuery = z.infer<typeof taskListQuerySchema>;
```

### Why each choice

| Choice | Why |
|---|---|
| Separate `create` / `update` / entity | Clients must not invent ids or bump version themselves on create |
| `trim().min(1)` | `"   "` is not a title |
| `parentTaskId` nullable | Top-level vs subtask in one table/collection |
| `version` required on update | Sets up optimistic concurrency (`409` later) |
| `z.coerce` on query `limit`/`offset` | Query strings are always strings |
| `.refine` on update | `PATCH` with only `{ version: 1 }` is useless |

If `z.iso.datetime()` fails on your Zod 4 build, use `z.string().datetime()` instead (same idea: ISO-8601 strings in JSON).

